package io.github.ningpp.compat;

import java.util.Arrays;

/** Replacement for System.MemoryExtensions (generated by CSharpToJava converter). */
public class MemoryExtensions {
    /** C# string.AsSpan() → ReadOnlySpan&lt;Character&gt; (converter maps char → Character). */
    public static ReadOnlySpan<Character> asSpan(String s) {
        if (s == null) return new ReadOnlySpan<>(new Character[0]);
        Character[] arr = new Character[s.length()];
        for (int i = 0; i < s.length(); i++) {
            arr[i] = s.charAt(i);
        }
        return new ReadOnlySpan<>(arr);
    }

    /** C# string.AsSpan(start, length) → ReadOnlySpan&lt;Character&gt;. */
    public static ReadOnlySpan<Character> asSpan(String s, int start, int length) {
        if (s == null) return new ReadOnlySpan<>(new Character[0]);
        Character[] arr = new Character[length];
        for (int i = 0; i < length; i++) {
            arr[i] = s.charAt(start + i);
        }
        return new ReadOnlySpan<>(arr);
    }

    /** C# string.AsMemory() → Java ReadOnlyMemory<Character> */
    public static ReadOnlyMemory<Character> asMemory(String s) {
        return ReadOnlyMemory.fromString(s);
    }

    /** C# string.AsMemory(start, length) → Java ReadOnlyMemory<Character> */
    public static ReadOnlyMemory<Character> asMemory(String s, int start, int length) {
        return ReadOnlyMemory.fromString(s, start, length);
    }

    /** C# char[].AsMemory() → Java ReadOnlyMemory<Character> */
    public static ReadOnlyMemory<Character> asMemory(char[] data) {
        if (data == null) return new ReadOnlyMemory<>();
        Character[] arr = new Character[data.length];
        for (int i = 0; i < data.length; i++) {
            arr[i] = data[i];
        }
        return new ReadOnlyMemory<>(arr);
    }

    /** C# char[].AsMemory(start, length) → Java ReadOnlyMemory<Character> */
    public static ReadOnlyMemory<Character> asMemory(char[] data, int start, int length) {
        if (data == null) return new ReadOnlyMemory<>();
        Character[] arr = new Character[length];
        for (int i = 0; i < length; i++) {
            arr[i] = data[start + i];
        }
        return new ReadOnlyMemory<>(arr, 0, length);
    }

    /** C# Span<byte> → Java ReadOnlySpan<Integer> (matches converter's byte→Integer mapping) */
    public static ReadOnlySpan<Integer> asSpan(byte[] data) {
        if (data == null) return new ReadOnlySpan<>(new Integer[0]);
        Integer[] arr = new Integer[data.length];
        for (int i = 0; i < data.length; i++) {
            arr[i] = data[i] & 0xFF;
        }
        return new ReadOnlySpan<>(arr);
    }

    /** C# ReadOnlySpan<byte> slice → Java ReadOnlySpan<Integer> (matches converter's byte→Integer mapping) */
    public static ReadOnlySpan<Integer> asSpan(byte[] data, int start, int length) {
        if (data == null) return new ReadOnlySpan<>(new Integer[0]);
        Integer[] arr = new Integer[length];
        for (int i = 0; i < length; i++) {
            arr[i] = data[start + i] & 0xFF;
        }
        return new ReadOnlySpan<>(arr);
    }

    /** C# T[].AsSpan() → Span&lt;T&gt; for reference-type arrays (e.g. string[] capslist).
     *  Primitive char[]/byte[] arrays bind to their more specific overloads. */
    @SuppressWarnings("unchecked")
    public static <T> Span<T> asSpan(T[] data) {
        return new Span<>(data == null ? (T[]) new Object[0] : data);
    }

    /** C# char[].AsSpan() → ReadOnlySpan&lt;Character&gt;. */
    public static ReadOnlySpan<Character> asSpan(char[] data) {
        if (data == null) return new ReadOnlySpan<>(new Character[0]);
        Character[] arr = new Character[data.length];
        for (int i = 0; i < data.length; i++) {
            arr[i] = data[i];
        }
        return new ReadOnlySpan<>(arr);
    }

    /** C# char[].AsSpan(start, length) → ReadOnlySpan&lt;Character&gt;. */
    public static ReadOnlySpan<Character> asSpan(char[] data, int start, int length) {
        if (data == null) return new ReadOnlySpan<>(new Character[0]);
        Character[] arr = new Character[length];
        for (int i = 0; i < length; i++) {
            arr[i] = data[start + i];
        }
        return new ReadOnlySpan<>(arr);
    }
}
